    rows, cols = len(grid), len(grid[0])
    bg = grid[0][0]

    # Find bounding box
    bp = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg:
                bp.add((r, c))

    if not bp:
        # No boundaries, fill at cmin, cmax
        return grid

    rmin, rmax = min(r for r, c in bp), max(r for r, c in bp)
    cmin, cmax = min(c for r, c in bp), max(c for r, c in bp)

    # Count pattern occurrences in bbox
    pattern_counts = Counter()
    for r in range(rmin, rmax + 1):
        bounds = tuple(sorted(c for c in range(cols) if grid[r][c] != bg))
        pattern_counts[bounds] += 1

    # Apply fill
    res = [row[:] for row in grid]
    for r in range(rmin, rmax + 1):
        bounds = sorted(c for c in range(cols) if grid[r][c] != bg)

        if len(bounds) >= 2:
            # Multi-boundary row: fill between consecutive if pattern is unique
            if pattern_counts[tuple(bounds)] == 1:
                for i in range(len(bounds) - 1):
                    for c in range(bounds[i] + 1, bounds[i + 1]):
                        res[r][c] = 2
        elif len(bounds) == 1:
            # Single boundary: fill at cmin, cmax (unconditionally in our tests)
            for c in [cmin, cmax]:
                res[r][c] = 2
        else:
            # No boundaries in this row: fill at cmin, cmax
